"""Read-only coding export change plan; never bypasses FileBroker or deletion approval."""

import re
from pathlib import Path

from Sprout.execution.verification_export import EXCLUDED, private_resource
from Sprout.execution.verification_run import input_manifest

# Generated by local test/lint execution, never source artifacts to import.
GENERATED_CACHES = frozenset({".pytest_cache", ".ruff_cache", "__pycache__"})


def artifact_plan(exported: Path, baseline: dict, *, oracle_paths) -> dict:
    if not oracle_paths:
        raise ValueError("Explicit protected oracle paths required")
    if exported.is_symlink() or not exported.is_dir():
        raise ValueError("Regular coding export directory required")
    if not isinstance(baseline, dict) or len(baseline) > 10000:
        raise ValueError("Bounded trusted baseline manifest required")
    total, count = 0, 0
    for entry in exported.rglob("*"):
        if entry.is_symlink() or not entry.resolve().is_relative_to(exported.resolve()):
            raise ValueError("Linked artifact forbidden")
        if entry.is_file():
            total += entry.stat().st_size
            count += 1
            if total > 32 * 1024 * 1024 or count > 10000:
                raise ValueError("Coding artifact limits exceeded")
    protections = []
    for name in oracle_paths:
        path = Path(name)
        if path.is_absolute() or ".." in path.parts or not path.parts:
            raise ValueError("Protected paths must be confined")
        protections.append(path)
    current = input_manifest(exported)
    folded = set()
    for name in sorted(set(baseline) | set(current)):
        path = Path(name)
        if (path.is_absolute() or ".." in path.parts or "\\" in name or ":" in name
                or not path.parts or name != path.as_posix()
                or name.casefold() in folded):
            raise ValueError("Unsafe or ambiguous artifact path")
        folded.add(name.casefold())
        excluded = {part.casefold() for part in path.parts} & EXCLUDED
        if excluded - GENERATED_CACHES:
            raise ValueError("Runtime/private artifact directory forbidden")
        if any(path == protected or path.is_relative_to(protected) for protected in protections):
            raise ValueError("Frozen oracle artifact forbidden")
        if excluded & GENERATED_CACHES:
            if name in baseline:
                raise ValueError("Generated cache cannot be a trusted source baseline")
            current.pop(name, None)
            continue
        if private_resource(path, exported):
            raise ValueError("Private/data artifact requires a supported adapter")
        if name in baseline and not re.fullmatch(r"[0-9a-f]{64}", str(baseline[name])):
            raise ValueError("Trusted baseline manifest malformed")
    changes = []
    for name in sorted(set(baseline) | set(current)):
        before, after = baseline.get(name), current.get(name)
        if before == after:
            continue
        changes.append({"path": name, "before_hash": before, "after_hash": after,
                        "operation": "delete" if after is None else "add" if before is None
                        else "modify", "requires_delete_approval": after is None})
    return {"changes": changes, "read_only": True, "applied": False,
            "authorization_granted": False}
